1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const COMPONENT_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
4	  rune: 25,
5	  moonstone: 25,
6	};
7	const MAIN_ITEM_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	};
13	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
14	  ...MAIN_ITEM_BASE_PREMIUM_BY_TYPE,
15	  ...COMPONENT_BASE_PREMIUM_BY_TYPE,
16	};
17	const COMPONENT_BLOCK_SIZE = 3;
18	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
19	const CURSED_SURCHARGE_RATE = 0.5;
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
22	const LOYALTY_MINIMUM_YEARS = 2;
23	const LOYALTY_DISCOUNT_RATE = 0.2;
24	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
25	
26	type Item = {
27	  type: string;
28	  material?: string;
29	  enchantment?: number;
30	  cursed?: boolean;
31	};
32	
33	type Step = {
34	  op: string;
35	  items: Item[];
36	};
37	
38	type Scenario = {
39	  customer: { yearsWithMHPCO: number };
40	  steps: Step[];
41	};
42	
43	type QuoteResult = {
44	  premium: number;
45	};
46	
47	type ScenarioOutput = {
48	  results: QuoteResult[];
49	};
50	
51	const isComponent = (item: Item): boolean =>
52	  item.type in COMPONENT_BASE_PREMIUM_BY_TYPE;
53	
54	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
55	  sameTypeItems.length === COMPONENT_BLOCK_SIZE &&
56	  sameTypeItems.every(isComponent);
57	
58	const groupByType = (items: Item[]): Item[][] => {
59	  const groups = new Map<string, Item[]>();
60	  for (const item of items) {
61	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
62	  }
63	  return [...groups.values()];
64	};
65	
66	const basePremiumForItem = (item: Item): number =>
67	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
68	
69	const basePremiumForGroup = (sameTypeItems: Item[]): number => {
70	  if (isComponentBlock(sameTypeItems)) return COMPONENT_BLOCK_BASE_PREMIUM;
71	  return sameTypeItems.reduce(
72	    (total, item) => total + basePremiumForItem(item),
73	    0,
74	  );
75	};
76	
77	const basePremiumForItems = (items: Item[]): number =>
78	  groupByType(items).reduce(
79	    (total, group) => total + basePremiumForGroup(group),
80	    0,
81	  );
82	
83	const amountAtRate = (
84	  basePremium: number,
85	  rate: number,
86	  applies?: boolean,
87	): number => (applies ? basePremium * rate : 0);
88	
89	const cursedSurcharge = (item: Item): number =>
90	  amountAtRate(basePremiumForItem(item), CURSED_SURCHARGE_RATE, item.cursed);
91	
92	const hasHighEnchantment = (item: Item): boolean =>
93	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
94	
95	const highEnchantmentSurcharge = (item: Item): number =>
96	  amountAtRate(
97	    basePremiumForItem(item),
98	    HIGH_ENCHANTMENT_SURCHARGE_RATE,
99	    hasHighEnchantment(item),
100	  );
101	
102	const totalItemSurcharges = (items: Item[]): number =>
103	  items.reduce(
104	    (total, item) =>
105	      total + cursedSurcharge(item) + highEnchantmentSurcharge(item),
106	    0,
107	  );
108	
109	const firstInsuranceSurcharge = (basePremium: number): number =>
110	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
111	
112	const isLoyalCustomer = (yearsWithMHPCO: number): boolean =>
113	  yearsWithMHPCO >= LOYALTY_MINIMUM_YEARS;
114	
115	const loyaltyDiscount = (basePremium: number, yearsWithMHPCO: number): number =>
116	  amountAtRate(
117	    basePremium,
118	    LOYALTY_DISCOUNT_RATE,
119	    isLoyalCustomer(yearsWithMHPCO),
120	  );
121	
122	const followUpDiscount = (basePremium: number, isFollowUp: boolean): number =>
123	  amountAtRate(basePremium, FOLLOW_UP_DISCOUNT_RATE, isFollowUp);
124	
125	const premiumBeforeProcessingFee = (
126	  items: Item[],
127	  yearsWithMHPCO: number,
128	  isFollowUp: boolean,
129	): number => {
130	  const basePremium = basePremiumForItems(items);
131	  return (
132	    basePremium +
133	    totalItemSurcharges(items) +
134	    firstInsuranceSurcharge(basePremium) -
135	    loyaltyDiscount(basePremium, yearsWithMHPCO) -
136	    followUpDiscount(basePremium, isFollowUp)
137	  );
138	};
139	
140	const isFollowUpQuote = (stepIndex: number): boolean => stepIndex > 0;
141	
142	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
143	  results: scenario.steps.map((step, stepIndex) => ({
144	    premium: Math.ceil(
145	      premiumBeforeProcessingFee(
146	        step.items,
147	        scenario.customer.yearsWithMHPCO,
148	        isFollowUpQuote(stepIndex),
149	      ) + PROCESSING_FEE,
150	    ),
151	  })),
152	});
